package dev.industrialtechnology.client;
import dev.industrialtechnology.expansion.*;import dev.industrialtechnology.railway.*;import dev.industrialtechnology.core.IndustrialTechnology;import net.minecraft.nbt.*;import net.minecraft.item.*;import net.minecraft.client.gui.GuiButton;import net.minecraft.client.renderer.RenderHelper;import org.lwjgl.opengl.GL11;
public final class GuiExpansion extends GuiTooltips {
 public final ExpansionContainer expansion;private NBTTagCompound state=new NBTTagCompound();public GuiExpansion(ExpansionContainer c){super(c);expansion=c;xSize=230;ySize=204;}public void receive(NBTTagCompound n){state=n;}
 @Override public void initGui(){super.initGui();buttonList.clear();if(expansion.train!=null){StockType t=expansion.train.stock;if(t.engine()){buttonList.add(new MetalButton(21,guiLeft+181,guiTop+30,43,18,"Drive",""));for(int i=0;i<5;i++)buttonList.add(new MetalButton(i,guiLeft+181,guiTop+51+i*22,43,18,new String[]{"+","Brake","STOP","Horn","Light"}[i],""));}if(t==StockType.STEAM)buttonList.add(new MetalButton(20,guiLeft+181,guiTop+164,43,18,"Water","Hold a water bucket on the cursor"));for(Object o:buttonList){GuiButton b=(GuiButton)o;if(b.id<5)b.enabled=mc.thePlayer.ridingEntity==expansion.train;}}}
 @Override protected void actionPerformed(GuiButton b){int e=expansion.train==null?0:expansion.train.getEntityId();IndustrialTechnology.network.sendToServer(new ExpansionCommand(expansion.windowId,e,b.id,0));}
 private void line(int y,String text){fontRendererObj.drawString(text,9,y,0xcbd6d7);}
 @Override protected void drawGuiContainerBackgroundLayer(float p,int mx,int my){drawRect(guiLeft,guiTop,guiLeft+xSize,guiTop+ySize,0xff202b31);drawRect(guiLeft+3,guiTop+3,guiLeft+xSize-3,guiTop+23,0xff35444b);if(expansion.train!=null){StockType t=expansion.train.stock;int n=t==StockType.FREIGHT?3:t==StockType.STEAM?1:0;for(int i=0;i<n;i++){int x=guiLeft+8+i*56,y=guiTop+76;drawRect(x,y,x+52,y+29,0xff536269);drawRect(x+1,y+1,x+51,y+28,0xff10191f);}}for(Object o:inventorySlots.inventorySlots){net.minecraft.inventory.Slot s=(net.minecraft.inventory.Slot)o;drawRect(guiLeft+s.xDisplayPosition-1,guiTop+s.yDisplayPosition-1,guiLeft+s.xDisplayPosition+17,guiTop+s.yDisplayPosition+17,0xff536269);drawRect(guiLeft+s.xDisplayPosition,guiTop+s.yDisplayPosition,guiLeft+s.xDisplayPosition+16,guiTop+s.yDisplayPosition+16,0xff10191f);}}
 @Override protected void drawGuiContainerForegroundLayer(int mx,int my){fontRendererObj.drawString(fontRendererObj.trimStringToWidth(state.getString("Title"),211),9,9,0xe5d69b);if(expansion.station!=null){line(31,state.getString("Status"));line(45,fontRendererObj.trimStringToWidth(state.getString("Vehicle"),210));line(59,"Transferred: "+state.getLong("Transferred"));line(73,expansion.station.kind()==0?state.getInteger("RF")+" / 2000000 RF":"Free logical capacity: "+state.getInteger("Free"));if(expansion.station.kind()==0){line(88,"Train: "+state.getInteger("TrainRF")+" / "+state.getInteger("TrainCapacity")+" RF");int capacity=state.getInteger("TrainCapacity"),progress=capacity<=0?0:(int)(100L*state.getInteger("TrainRF")/capacity);line(102,"Charge progress: "+progress+"%");}return;}
  StockType t=expansion.train.stock;line(30,String.format(java.util.Locale.ROOT,"%.1f km/h  %d wagons",state.getDouble("Speed"),state.getInteger("Wagons")));line(42,"Power "+state.getInteger("Throttle")+"% Brake "+state.getInteger("Brake")+"%");line(54,t==StockType.STEAM?state.getInteger("Temperature")+" C  Water "+state.getInteger("Water")+" mB":t.electric()?state.getInteger("RF")+" / "+state.getInteger("Capacity")+" RF":"Cargo: "+state.getInteger("TotalCargo")+" items");line(65,String.format(java.util.Locale.ROOT,"Mass %.1f t",state.getDouble("Mass")));LogicalCargo cargo=new LogicalCargo(t==StockType.STEAM?1:3,t==StockType.STEAM);cargo.load(state.getTagList(t==StockType.STEAM?"Fuel":"Cargo",10));if(t==StockType.FREIGHT||t==StockType.STEAM)for(int i=0;i<cargo.slots();i++){ItemStack item=cargo.type(i);if(item!=null){GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);try{RenderHelper.enableGUIStandardItemLighting();itemRender.renderItemAndEffectIntoGUI(fontRendererObj,mc.getTextureManager(),item,11+i*56,77);}finally{GL11.glPopAttrib();}}fontRendererObj.drawString(cargo.count(i)+"/"+cargo.capacity(i),10+i*56,95,0xe0dfc7);}String status=state.getString("Status");if(t==StockType.FREIGHT)status="Click bin: insert / take";fontRendererObj.drawString(fontRendererObj.trimStringToWidth(status,167),8,108,0x97b5bf);
 }
 @Override protected void mouseClicked(int x,int y,int button){if(expansion.train!=null&&(button==0||button==1)){StockType t=expansion.train.stock;int n=t==StockType.FREIGHT?3:t==StockType.STEAM?1:0;for(int i=0;i<n;i++)if(x>=guiLeft+8+i*56&&x<guiLeft+60+i*56&&y>=guiTop+76&&y<guiTop+105){IndustrialTechnology.network.sendToServer(new ExpansionCommand(expansion.windowId,expansion.train.getEntityId(),10+i,(button==1?1:0)|(isShiftKeyDown()?2:0)));return;}}super.mouseClicked(x,y,button);}
 @Override public void drawScreen(int x,int y,float p){GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);try{GL11.glColor4f(1,1,1,1);super.drawScreen(x,y,p);if(expansion.train!=null){StockType t=expansion.train.stock;int slots=t==StockType.STEAM?1:t==StockType.FREIGHT?3:0;LogicalCargo cargo=new LogicalCargo(slots,t==StockType.STEAM);cargo.load(state.getTagList(t==StockType.STEAM?"Fuel":"Cargo",10));for(int i=0;i<slots;i++)if(x>=guiLeft+8+i*56&&x<guiLeft+60+i*56&&y>=guiTop+76&&y<guiTop+105){ItemStack item=cargo.type(i);drawHoveringText(java.util.Arrays.asList(item==null?"Empty cargo bin":item.getDisplayName(),cargo.count(i)+" / "+cargo.capacity(i),"Left: insert / take stack","Right: one item; Shift: to inventory"),x,y,fontRendererObj);}}}finally{GL11.glPopAttrib();}}
}
